{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-shl3Q6/src/document.js","content":"/**
 * The document being built while reading the configuration: a tree of table,
 * array-of-tables, array and scalar nodes, plus the operations `[name]`,
 * `[[name]]` and `<dotted name> = <value>` directives need to walk and mutate
 * it while enforcing the "already defined" rules.
 */
import { fail } from './errors.js'

export function newTable(explicit) {
  return { t: 'table', map: new Map(), explicit }
}

export function newArrayOfTables() {
  return { t: 'array-of-tables', arr: [] }
}

/** Compares two strings by Unicode code point, ascending. */
export function compareByCodePoint(a, b) {
  const ac = Array.from(a)
  const bc = Array.from(b)
  const len = Math.min(ac.length, bc.length)
  for (let i = 0; i < len; i++) {
    const ca = ac[i].codePointAt(0)
    const cb = bc[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ac.length - bc.length
}

export function orderedKeys(tableNode) {
  return Array.from(tableNode.map.keys()).sort(compareByCodePoint)
}

/**
 * Walks one non-final component of a dotted name, creating an implicit
 * table when the name is absent and following an array of tables to its
 * last element, per the "walking through an array of tables uses its last
 * element" rule.
 */
export function descendIntermediate(node, name, path, lineNo) {
  const existing = node.map.get(name)
  if (existing === undefined) {
    const t = newTable(false)
    node.map.set(name, t)
    return t
  }
  if (existing.t === 'table') return existing
  if (existing.t === 'array-of-tables') return existing.arr[existing.arr.length - 1]
  fail(lineNo, `${path.join('.')} is not a table`)
}

/** Applies a `<dotted name> = <value>` directive inside `tableNode`. */
export function assignInto(tableNode, names, value, pathPrefix, lineNo) {
  let node = tableNode
  const path = pathPrefix.slice()
  for (let i = 0; i < names.length - 1; i++) {
    path.push(names[i])
    node = descendIntermediate(node, names[i], path, lineNo)
  }
  const last = names[names.length - 1]
  path.push(last)
  if (node.map.has(last)) fail(lineNo, `key ${path.join('.')} is defined twice`)
  node.map.set(last, value)
}

/**
 * Applies a `[name]` or `[[name]]` header, always resolved from the document
 * root. Returns the table that becomes current.
 */
export function applyHeader(root, names, isArray, lineNo) {
  let node = root
  const path = []
  for (let i = 0; i < names.length - 1; i++) {
    path.push(names[i])
    node = descendIntermediate(node, names[i], path, lineNo)
  }
  const last = names[names.length - 1]
  path.push(last)
  const existing = node.map.get(last)

  if (!isArray) {
    if (existing === undefined) {
      const t = newTable(true)
      node.map.set(last, t)
      return t
    }
    if (existing.t === 'table') {
      if (existing.explicit) fail(lineNo, `table ${path.join('.')} is defined twice`)
      existing.explicit = true
      return existing
    }
    fail(lineNo, `${path.join('.')} is not a table`)
  }

  let arrNode
  if (existing === undefined) {
    arrNode = newArrayOfTables()
    node.map.set(last, arrNode)
  } else if (existing.t === 'array-of-tables') {
    arrNode = existing
  } else {
    fail(lineNo, `${path.join('.')} is not an array of tables`)
  }
  const t = newTable(false)
  arrNode.arr.push(t)
  return t
}
"}

