{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-shl3Q6/src/parser.js","content":"/**
 * Parses one configuration document (already split into lines) into a tree
 * of table, array-of-tables, array and scalar nodes, applying the header and
 * assignment rules from the specification.
 */
import { fail } from './errors.js'
import { newTable, applyHeader, assignInto } from './document.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INT_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

class LineParser {
  constructor(line, lineNo) {
    this.line = line
    this.len = line.length
    this.pos = 0
    this.lineNo = lineNo
  }

  fail(reason) {
    fail(this.lineNo, reason)
  }

  atEnd() {
    return this.pos >= this.len
  }

  peek() {
    return this.line[this.pos]
  }

  /** Skips spaces and tabs only; does not treat `#`/`;` specially. */
  skipSpaces() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  /**
   * Skips spaces and tabs, then, if a `#` or `;` outside a quoted string
   * follows, treats the rest of the line as a comment.
   */
  skipSpacesAndComment() {
    this.skipSpaces()
    if (!this.atEnd() && (this.peek() === '#' || this.peek() === ';')) this.pos = this.len
  }

  isNameStart(ch) {
    return ch !== undefined && (ch === '"' || ch === "'" || NAME_CHAR.test(ch))
  }

  parseDottedName() {
    const names = []
    while (true) {
      this.skipSpacesAndComment()
      const ch = this.peek()
      if (!this.isNameStart(ch)) this.fail('expected a name')
      if (ch === '"') names.push(this.parseBasicString())
      else if (ch === "'") names.push(this.parseLiteralString())
      else {
        const start = this.pos
        while (!this.atEnd() && NAME_CHAR.test(this.peek())) this.pos++
        names.push(this.line.slice(start, this.pos))
      }
      this.skipSpaces()
      if (!this.atEnd() && this.peek() === '.') {
        this.pos++
        continue
      }
      break
    }
    return names
  }

  parseBasicString() {
    this.pos++ // opening quote
    let out = ''
    while (true) {
      if (this.atEnd()) this.fail('unterminated string')
      const ch = this.peek()
      if (ch === '"') {
        this.pos++
        return out
      }
      if (ch === '\\') {
        this.pos++
        if (this.atEnd()) this.fail('unterminated string')
        const esc = this.peek()
        switch (esc) {
          case '"':
            out += '"'
            this.pos++
            break
          case '\\':
            out += '\\'
            this.pos++
            break
          case 'n':
            out += '\n'
            this.pos++
            break
          case 't':
            out += '\t'
            this.pos++
            break
          case 'r':
            out += '\r'
            this.pos++
            break
          case '0':
            out += '\0'
            this.pos++
            break
          case 'u': {
            this.pos++
            if (this.pos + 4 > this.len) this.fail('unterminated string')
            const hex = this.line.slice(this.pos, this.pos + 4)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.fail('invalid escape \\u')
            out += String.fromCharCode(parseInt(hex, 16))
            this.pos += 4
            break
          }
          default:
            this.fail(`invalid escape \\${esc}`)
        }
      } else {
        out += ch
        this.pos++
      }
    }
  }

  parseLiteralString() {
    this.pos++ // opening quote
    const start = this.pos
    while (true) {
      if (this.atEnd()) this.fail('unterminated string')
      if (this.peek() === "'") {
        const s = this.line.slice(start, this.pos)
        this.pos++
        return s
      }
      this.pos++
    }
  }

  /** Scans a bare token: a run of characters up to whitespace or `,`, `]`, `}`. */
  scanBareToken() {
    const start = this.pos
    while (!this.atEnd() && ![' ', '\t', ',', ']', '}'].includes(this.peek())) this.pos++
    return this.line.slice(start, this.pos)
  }

  parseValue(pathPrefix) {
    this.skipSpacesAndComment()
    if (this.atEnd() || this.peek() === ',' || this.peek() === ']' || this.peek() === '}') {
      this.fail('expected a value')
    }
    const ch = this.peek()
    if (ch === '"') return { t: 'string', v: this.parseBasicString() }
    if (ch === "'") return { t: 'string', v: this.parseLiteralString() }
    if (ch === '[') return this.parseArray(pathPrefix)
    if (ch === '{') return this.parseInlineTable(pathPrefix)

    const token = this.scanBareToken()
    if (token === 'true') return { t: 'boolean', v: true }
    if (token === 'false') return { t: 'boolean', v: false }
    if (INT_RE.test(token)) return { t: 'integer', v: toBigInt(token) }
    if (FLOAT_RE.test(token)) return { t: 'float', v: Number(token.replace(/_/g, '')) }
    this.fail(`invalid value ${token}`)
  }

  parseArray(pathPrefix) {
    this.pos++ // consume '['
    const items = []
    this.skipSpacesAndComment()
    if (this.atEnd()) this.fail('unterminated array')
    if (this.peek() === ']') {
      this.pos++
      return { t: 'array', items }
    }
    while (true) {
      items.push(this.parseValue(pathPrefix))
      this.skipSpacesAndComment()
      if (this.atEnd()) this.fail('unterminated array')
      const ch = this.peek()
      if (ch === ',') {
        this.pos++
        this.skipSpacesAndComment()
        if (this.atEnd()) this.fail('unterminated array')
        if (this.peek() === ']') {
          this.pos++
          return { t: 'array', items }
        }
        continue
      }
      if (ch === ']') {
        this.pos++
        return { t: 'array', items }
      }
      this.fail('unterminated array')
    }
  }

  parseInlineTable(pathPrefix) {
    this.pos++ // consume '{'
    const node = newTable(true)
    this.skipSpacesAndComment()
    if (this.atEnd()) this.fail('unterminated inline table')
    if (this.peek() === '}') {
      this.pos++
      return node
    }
    while (true) {
      const names = this.parseDottedName()
      this.skipSpacesAndComment()
      if (this.atEnd() || this.peek() !== '=') this.fail('expected = in an inline table')
      this.pos++
      const value = this.parseValue(pathPrefix.concat(names))
      assignInto(node, names, value, pathPrefix, this.lineNo)
      this.skipSpacesAndComment()
      if (this.atEnd()) this.fail('unterminated inline table')
      const ch = this.peek()
      if (ch === ',') {
        this.pos++
