export function parseDocument(lines) {
  const root = newTable(true)
  let currentTable = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const idx = firstNonSpaceTab(line)
    if (idx === -1) continue
    const first = line[idx]
    if (first === '#' || first === ';') continue

